add_filter( 'get_product_search_form', 'perfectpixel_custom_product_search_form' );

function perfectpixel_custom_product_search_form() {
	static $index = 0;
	$index++;
	$id = 'perfectpixel-product-search-' . $index;
	return sprintf(
		'<form role="search" method="get" class="woocommerce-product-search perfectpixel-product-search" action="%1$s" style="display:flex;gap:.5em">
			<label class="screen-reader-text" for="%2$s">%3$s</label>
			<input type="search" id="%2$s" class="search-field" placeholder="%3$s" value="%4$s" name="s" autocomplete="off" style="flex:1">
			<button type="submit" class="button">%5$s</button>
			<input type="hidden" name="post_type" value="product">
		</form>',
		esc_url( home_url( '/' ) ),
		esc_attr( $id ),
		esc_attr( '{{search_form_placeholder}}' ),
		esc_attr( get_search_query() ),
		esc_html( '{{search_form_button}}' )
	);
}
